WITH filtered AS (SELECT id, channel, promo_code, discount_pct, UPPER(promo_code) AS promo_code_upper, DATEDIFF(ends_on, starts_on) AS days_starts_on_to_ends_on, COALESCE(channel, 'UNKNOWN') AS channel_filled FROM promotions WHERE starts_on BETWEEN '2023-10-12' AND '2024-09-02') SELECT id, channel FROM filtered INTERSECT SELECT id, channel FROM promotions WHERE ends_on > '2023-07-04'
